#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { execFileSync, spawnSync } from "node:child_process";
import { gunzipSync } from "node:zlib";

const VERSION = "3.0.0";
const BRANCH = "agent/pfotentechnik-internal-linking-3";
const args = new Set(process.argv.slice(2));
const force = args.has("--force");
const skipValidation = args.has("--no-validate");
const publish = args.has("--publish");
const noCommit = args.has("--no-commit");
const payload = JSON.parse(gunzipSync(Buffer.from("", "base64")).toString("utf8"));

const exists = (value) => fs.existsSync(value);
const findRoot = () => {
  let current = process.cwd();
  while (true) {
    if (exists(path.join(current, "apps/pfotentechnik/package.json")) && exists(path.join(current, "packages/affiliate-core/package.json"))) return current;
    const parent = path.dirname(current);
    if (parent === current) throw new Error("Repository-Wurzel nicht gefunden. Starte den Installer im Repository Yushamon/affiliate-template.");
    current = parent;
  }
};
const root = findRoot();
process.chdir(root);

const run = (command, commandArgs, options = {}) => {
  const printable = [command, ...commandArgs].join(" ");
  console.log(`
> ${printable}`);
  const result = spawnSync(command, commandArgs, { cwd: root, stdio: "inherit", shell: false, ...options });
  if (result.status !== 0) throw new Error(`Befehl fehlgeschlagen (${result.status}): ${printable}`);
};
const output = (command, commandArgs) => execFileSync(command, commandArgs, { cwd: root, encoding: "utf8" }).trim();
const gitAvailable = spawnSync("git", ["--version"], { stdio: "ignore" }).status === 0 && exists(path.join(root, ".git"));
const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupRoot = path.join(root, ".patch-backups", `pfotentechnik-internal-linking-${VERSION}-${timestamp}`);
const changed = new Set();

const expectedAnchors = {
  "packages/affiliate-core/src/linking/types.ts": ["export type InternalLinkGroup", "InternalLinkDefinition"],
  "packages/affiliate-core/src/linking/rules.ts": ["internalLinkRules"],
  "packages/affiliate-core/src/linking/linkEngine.ts": ["findInternalLinkMatches", "selectInternalLinkMatches"],
  "packages/affiliate-core/src/linking/htmlLinker.ts": ["createInternalLinkedHtml"],
  "packages/affiliate-core/src/linking/generator.ts": ["generateInternalLinkDictionary"],
  "packages/affiliate-core/src/components/AutoLinkContent.astro": ["createInternalLinkedHtml", "Astro.slots.render"],
  "apps/pfotentechnik/src/domain/content/internalLinks.ts": ["getInternalLinkDefinitions"],
  "apps/pfotentechnik/src/domain/content/related.ts": ["getRelatedContent"],
  "apps/pfotentechnik/src/domain/recommendationLinks.ts": ["buildProductNextSteps", "buildComparisonNextSteps"],
  "apps/pfotentechnik/scripts/build-content-graph.mjs": ["content-graph.json"],
  "scripts/audit-internal-links.mjs": ["audit-internal-links"],
  "apps/pfotentechnik/src/lib/seo/advisor/loadContent.ts": ["loadAdvisorContent"],
  "apps/pfotentechnik/src/lib/seo/advisor/index.ts": ["buildSeoAdvisor"],
  "apps/pfotentechnik/src/content/schema/base.ts": ["baseContentSchema"]
};

const backup = (relative) => {
  const source = path.join(root, relative);
  if (!exists(source)) return;
  const target = path.join(backupRoot, relative);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.copyFileSync(source, target);
};

const preflight = () => {
  for (const [relative, anchors] of Object.entries(expectedAnchors)) {
    const target = path.join(root, relative);
    if (!exists(target)) throw new Error(`Vorprüfung fehlgeschlagen: ${relative} fehlt.`);
    const current = fs.readFileSync(target, "utf8");
    const desired = payload[relative];
    if (current === desired) continue;
    if (!force && anchors.some((anchor) => !current.includes(anchor))) {
      throw new Error(`Vorprüfung fehlgeschlagen: ${relative} entspricht nicht der erwarteten Architektur. Nutze --force nur nach manueller Prüfung.`);
    }
  }
  for (const relative of Object.keys(payload)) {
    if (expectedAnchors[relative]) continue;
    const target = path.join(root, relative);
    if (exists(target) && fs.readFileSync(target, "utf8") !== payload[relative] && !force) {
      throw new Error(`Vorprüfung fehlgeschlagen: Neue Zieldatei existiert bereits mit anderem Inhalt: ${relative}`);
    }
  }
};

const prepareBranch = () => {
  if (!gitAvailable) return { clean: false, branch: "" };
  const status = output("git", ["status", "--porcelain"]);
  const clean = !status;
  const current = output("git", ["branch", "--show-current"]);
  if (clean && current !== BRANCH) {
    const branchExists = spawnSync("git", ["show-ref", "--verify", "--quiet", `refs/heads/${BRANCH}`], { cwd: root }).status === 0;
    run("git", branchExists ? ["switch", BRANCH] : ["switch", "-c", BRANCH]);
  } else if (!clean) {
    console.warn(`\nWARN Arbeitsbaum ist nicht sauber. Der Installer bleibt auf dem aktuellen Branch und erstellt keinen automatischen Commit.`);
  }
  return { clean, branch: clean ? BRANCH : current };
};

const patchPackageJson = (relative, mutate) => {
  const target = path.join(root, relative);
  backup(relative);
  const value = JSON.parse(fs.readFileSync(target, "utf8"));
  mutate(value);
  const next = `${JSON.stringify(value, null, 2)}
`;
  if (fs.readFileSync(target, "utf8") !== next) { fs.writeFileSync(target, next); changed.add(relative); }
};

const writePayload = () => {
  for (const [relative, content] of Object.entries(payload)) {
    const target = path.join(root, relative);
    if (exists(target) && fs.readFileSync(target, "utf8") === content) continue;
    backup(relative);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content, "utf8");
    changed.add(relative);
  }
  patchPackageJson("packages/affiliate-core/package.json", (pkg) => {
    pkg.scripts ??= {};
    pkg.scripts.test = "node --experimental-strip-types --test src/affiliate/*.test.ts src/linking/*.test.ts";
  });
  patchPackageJson("apps/pfotentechnik/package.json", (pkg) => {
    pkg.scripts ??= {};
    pkg.scripts["test:internal-linking"] = "node --experimental-strip-types --test test/internal-linking-3.test.mjs";
    pkg.scripts["audit:internal-links"] = "node ../../scripts/audit-internal-links.mjs";
    pkg.scripts["audit:internal-links:strict"] = "node ../../scripts/audit-internal-links.mjs --strict";
  });
};

const validations = [
  ["npm", ["--workspace", "packages/affiliate-core", "test"]],
  ["npm", ["--workspace", "apps/pfotentechnik", "run", "test:internal-linking"]],
  ["npm", ["--workspace", "apps/pfotentechnik", "run", "build:content-graph"]],
  ["npm", ["--workspace", "apps/pfotentechnik", "run", "audit:content-graph"]],
  ["npm", ["--workspace", "apps/pfotentechnik", "run", "lint:content"]],
  ["npm", ["--workspace", "apps/pfotentechnik", "run", "audit:repository"]],
  ["node", ["scripts/audit-internal-links.mjs", "--strict"]],
  ["npm", ["run", "build:pfotentechnik"]]
];

const main = () => {
  console.log(`[pfotentechnik-internal-linking-${VERSION}] Vorprüfung`);
  preflight();
  const gitState = prepareBranch();
  writePayload();
  console.log(`
Geändert/erstellt: ${changed.size} Dateien`);
  console.log(`Backups: ${path.relative(root, backupRoot)}`);

  if (!skipValidation) {
    for (const [command, commandArgs] of validations) run(command, commandArgs);
    for (const generated of [
      "apps/pfotentechnik/src/generated/content-graph.json",
      "apps/pfotentechnik/reports/internal-linking/internal-link-audit.json",
      "apps/pfotentechnik/reports/internal-linking/internal-link-audit.md",
      "apps/pfotentechnik/reports/internal-linking/internal-link-migration.md"
    ]) if (exists(path.join(root, generated))) changed.add(generated);
  }

  if (gitAvailable && gitState.clean && !noCommit) {
    const paths = [...changed].filter((relative) => exists(path.join(root, relative)));
    if (paths.length) {
      run("git", ["add", "--", ...paths]);
      const staged = output("git", ["diff", "--cached", "--name-only"]);
      if (staged) run("git", ["commit", "-m", "feat(pfotentechnik): implement internal linking 3.0"]);
    }
    if (publish) {
      run("git", ["push", "-u", "origin", BRANCH]);
      if (spawnSync("gh", ["--version"], { stdio: "ignore" }).status === 0) {
        const existing = spawnSync("gh", ["pr", "view", BRANCH, "--json", "number"], { cwd: root, stdio: "ignore" }).status === 0;
        if (!existing) run("gh", ["pr", "create", "--draft", "--base", "main", "--head", BRANCH, "--title", "feat(pfotentechnik): Internal Linking 3.0", "--body", "Zentrale Linktaxonomie, globale HTML-Auswahl, gemeinsames Seitenbudget, Related/Next-Steps-Synchronisierung, Content-Graph- und SEO-Co-Pilot-Korrekturen sowie Strict-Audit und Tests."]);
      } else {
        console.warn("gh CLI fehlt. Branch wurde gepusht, der Draft-PR muss in GitHub geöffnet werden.");
      }
    }
  }

  console.log(`
[pfotentechnik-internal-linking-${VERSION}] Abgeschlossen.`);
  console.log(`Branch: ${gitAvailable ? output("git", ["branch", "--show-current"]) : "kein Git erkannt"}`);
  console.log(`Core-Tests: 16 Szenarien. PfotenTechnik-Tests: 9 Szenarien.`);
  console.log("Berichte: apps/pfotentechnik/reports/internal-linking/");
};

try { main(); } catch (error) {
  console.error(`
[pfotentechnik-internal-linking-${VERSION}] FEHLER: ${error instanceof Error ? error.message : String(error)}`);
  console.error(`Backups: ${path.relative(root, backupRoot)}`);
  process.exit(1);
}
